import { test, expect } from '@playwright/test';

test.describe('Product Sorting by Price', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
  });

  test('should sort products by price from low to high', async ({ page }) => {
    await page.selectOption('[data-test="product-sort-container"]', 'lohi');
    const prices = await page.$$eval('.inventory_item_price', elements => 
      elements.map(el => parseFloat(el.textContent.replace('$', '')))
    );
    const sortedPrices = [...prices].sort((a, b) => a - b);
    expect(prices).toEqual(sortedPrices);
  });

  test('should display the cheapest item first after sorting', async ({ page }) => {
    await page.selectOption('[data-test="product-sort-container"]', 'lohi');
    const firstItemPrice = await page.textContent('.inventory_item_price:first-child');
    const firstPriceValue = parseFloat(firstItemPrice.replace('$', ''));

    const allPrices = await page.$$eval('.inventory_item_price', elements => 
      elements.map(el => parseFloat(el.textContent.replace('$', '')))
    );

    expect(firstPriceValue).toBeLessThanOrEqual(Math.min(...allPrices));
  });
});
